"""Class for handling all Applications related to remote Mosaiq automation"""

from ..desktop.application_aut import Application_AUT

class MosaiqAutController(Application_AUT):

    def __init__(self, serverAddress: str, serverPort: int):
        Application_AUT.__init__(self, serverAddress, serverPort)

    @classmethod
    def mosaiq_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7401):
        """Function to modify variables in the default MosaiqAutController class to target a Mosaiq application,
        on a system, with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number to attach to running instance of Mosaiq (can be used for debugging purposes)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = "accwin"
        aut_cls.attach_port = str(attachPort)
        return aut_cls

    @classmethod
    def dcmtree_aut(cls, serverAddress: str, serverPort: int):
        """Function to modify variables in the default MosaiqAutController class to target a DCMTree application,
        on a system, with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = "DCMtree"
        return aut_cls

    @classmethod
    def embedded_explorer_aut(cls, serverAddress: str, serverPort: int, folderPath: str = ""):
        """Function to modify variables in the default MosaiqAutController class to target a embedded_explorer_64 application,
        on a system, with a squish server running.
        (Can also be launched with a folderPath argument so that the application is launched pointing at that path on startup)

        :param folderPath: Folder Path string which will be passed as a launch argument.
        This will cause the Embedded Explorer application startup pointed at that location.
        :type folderPath: str, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = "embedded_explorer_64"
        aut_cls.arguments = folderPath
        return aut_cls
